function Field({ label, value, onChange, type = "text", dir, multiline = false, placeholder }: { label: string; value: string | number; onChange: (value: string) => void; type?: string; dir?: string; multiline?: boolean; placeholder?: string }) {
  return <label className="cms-field"><span>{label}</span>{multiline ? <textarea value={value} dir={dir} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} /> : <input type={type} value={value} dir={dir} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} />}</label>;
}

function LocalizedFields({ label, value, onChange, multiline = false, language }: { label: string; value: LocalizedText; onChange: (value: LocalizedText) => void; multiline?: boolean; language: Lang }) {
  const [activeLanguage, setActiveLanguage] = useState<Lang>(language);
  const text = value?.[activeLanguage] ?? "";
  const copyToAll = localizedFieldUi[language];
  return <fieldset className="cms-localized"><legend>{label}</legend><div className="cms-localized-toolbar"><div className="cms-language-tabs" role="group" aria-label={label}>{(["he", "ar", "en"] as const).map((lang) => <button key={lang} type="button" className="cms-language-tab" data-language={lang} aria-pressed={activeLanguage === lang} onClick={() => setActiveLanguage(lang)}>{localeNames[lang]}</button>)}</div><button type="button" className="cms-copy-all-languages" title={copyToAll.copyTitle} aria-label={copyToAll.copyTitle} onClick={() => onChange({ he: text, ar: text, en: text })}><Copy size={13}/><span>{copyToAll.copyToAll}</span></button></div><div className="cms-localized-editor"><Field label={localeNames[activeLanguage]} value={text} dir={activeLanguage === "en" ? "ltr" : "rtl"} multiline={multiline} onChange={(nextText) => onChange({ ...value, [activeLanguage]: nextText })} /></div></fieldset>;
}

function ProductRowsEditor({ kind, rows, language, labels, onChange }: { kind: "specs" | "features"; rows: string[][]; language: Lang; labels: Record<string, string>; onChange: (rows: string[][]) => void }) {
  const [activeLanguage, setActiveLanguage] = useState<Lang>(language);
  const [bulkText, setBulkText] = useState("");
  const [bulkError, setBulkError] = useState("");
  const activeIndex = languageOrder.indexOf(activeLanguage);
  const rowUi = productRowsUi[language];
  const updateCell = (rowIndex: number, column: number, text: string) => onChange(rows.map((row, index) => index === rowIndex ? row.map((cell, cellIndex) => cellIndex === column ? text : cell) : row));
  const hasActiveLanguageText = rows.some((row) => !!row[activeIndex]?.trim());
  const copyLanguageToAll = () => onChange(rows.map((row) => row.map((cell, column) => column < 3 && row[activeIndex]?.trim() ? row[activeIndex] : cell)));
  const addPastedRows = () => {
    const parsed = bulkText.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).flatMap((line) => {
      if (kind === "features") {
        const row = ["", "", ""];
        row[activeIndex] = line;
        return [row];
      }
      const separator = line.indexOf("|");
      if (separator < 1 || !line.slice(separator + 1).trim()) return [];
      const row = ["", "", "", ""];
      row[activeIndex] = line.slice(0, separator).trim();
      row[3] = line.slice(separator + 1).trim();
      return [row];
    });
    if (!parsed.length) {
      setBulkError(kind === "specs" ? rowUi.pasteSpecHint : rowUi.pasteFeatureHint);
      return;
    }
    onChange([...rows, ...parsed]);
    setBulkText("");
    setBulkError("");
  };
  const title = kind === "specs" ? labels.specifications : labels.features;
  return <div className={`cms-product-row-editor cms-product-row-editor-${kind}`}>
    <div className="cms-product-row-toolbar">
      <div className="cms-language-tabs" role="group" aria-label={`${title} language`}>
        {(["he", "ar", "en"] as const).map((lang) => <button key={lang} type="button" className="cms-language-tab" data-language={lang} aria-pressed={activeLanguage === lang} onClick={() => setActiveLanguage(lang)}>{localeNames[lang]}</button>)}
      </div>
      <button type="button" className="cms-copy-all-languages" onClick={copyLanguageToAll} disabled={!hasActiveLanguageText} title={localizedFieldUi[language].copyTitle}><Copy size={13}/><span>{rowUi.copyLanguage}</span></button>
    </div>
    <p className="cms-product-row-hint">{language === "he" ? `העורך מציג כרגע ${localeNames[activeLanguage]}. ניתן להחליף שפה לכל הרשימה.` : language === "ar" ? `التحرير الآن باللغة ${localeNames[activeLanguage]}. يمكن تبديل لغة القائمة كلها من هنا.` : `Editing ${localeNames[activeLanguage]}. Switch the language for the entire list here.`}</p>
    <div className="cms-product-row-list">
      {rows.map((row, index) => <div className="cms-product-data-row" key={`${kind}-${index}`}>
        <Field label={`${title} ${index + 1}`} value={row[activeIndex] ?? ""} dir={activeLanguage === "en" ? "ltr" : "rtl"} onChange={(text) => updateCell(index, activeIndex, text)} />
        {kind === "specs" && <Field label={labels.value} value={row[3] ?? ""} dir="auto" onChange={(text) => updateCell(index, 3, text)} />}
        <button type="button" className="cms-delete" aria-label={labels.delete} title={labels.delete} onClick={() => onChange(rows.filter((_, rowIndex) => rowIndex !== index))}><Trash2 size={14}/></button>
      </div>)}
    </div>
    <button type="button" className="cms-add-row" onClick={() => onChange([...rows, kind === "specs" ? ["", "", "", ""] : ["", "", ""]])}><Plus size={14}/>{labels.addRow}</button>
    <details className="cms-product-bulk-entry">
      <summary><span>{rowUi.pasteRows}</span><ChevronDown size={14}/></summary>
      <p>{kind === "specs" ? rowUi.pasteSpecHint : rowUi.pasteFeatureHint}</p>
      <textarea aria-label={rowUi.pasteRows} dir={activeLanguage === "en" ? "ltr" : "rtl"} placeholder={kind === "specs" ? rowUi.pasteSpecPlaceholder : rowUi.pasteFeaturePlaceholder} value={bulkText} onChange={(event) => { setBulkText(event.target.value); setBulkError(""); }} />
      {bulkError && <span className="cms-product-bulk-error" role="status">{bulkError}</span>}
      <button type="button" className="cms-add-row" onClick={addPastedRows}><Plus size={14}/>{rowUi.addPasted}</button>
    </details>
  </div>;
}

function Toggle({ label, checked, onChange }: { label: string; checked: boolean; onChange: (value: boolean) => void }) {
  return <label className="cms-toggle"><input type="checkbox" checked={checked} onChange={(event) => onChange(event.target.checked)} /><span>{label}</span></label>;
}

function Card({ title, children, action }: { title: string; children: React.ReactNode; action?: React.ReactNode }) {
  return <section className="admin-panel cms-card"><div className="admin-panel-head"><div><h2>{title}</h2></div>{action}</div><div className="cms-card-body">{children}</div></section>;
}

export function CmsPanel({ value, onChange, onSave, busy, language }: { value: SiteContent; onChange: (value: SiteContent) => void; onSave: (value: SiteContent) => void; busy: boolean; language: Lang }) {
  const labels = ui[language];
  const roomLabel = language === "he" ? "גודל חלל מומלץ" : language === "ar" ? "المساحة المناسبة" : "Recommended room size";
  const categoryLabel = language === "he" ? "קטגוריית מוצר" : language === "ar" ? "تصنيف المنتج" : "Product category";
  const mainImageLabel = language === "he" ? "תמונה ראשית למוצר" : language === "ar" ? "الصورة الرئيسية للمنتج" : "Main product image";
  const galleryLabel = language === "he" ? "תמונות נוספות בגלריה" : language === "ar" ? "صور إضافية في المعرض" : "Additional gallery images";
  const addGalleryImageLabel = language === "he" ? "הוספת תמונה לגלריה" : language === "ar" ? "إضافة صورة للمعرض" : "Add image to gallery";
  const productShareLabel = language === "he" ? "תמונת שיתוף שונה (רשות; ברירת מחדל: התמונה הראשית)" : language === "ar" ? "صورة مشاركة مختلفة (اختياري؛ الافتراضية هي الصورة الرئيسية)" : "Different share image (optional; defaults to main image)";
  const roomCategoryIds = new Set(["bedroom", "living", "large"]);
  const roomNames = language === "he" ? ["חדר שינה", "חלל מגורים", "חלל גדול"] : language === "ar" ? ["غرفة نوم", "مساحة معيشة", "مساحة كبيرة"] : ["Bedroom", "Living space", "Large space"];
  const sectionNames: Record<string, string> = { hero: language === "he" ? "מקטע פתיחה" : language === "ar" ? "الواجهة الرئيسية" : "Hero", benefits: labels.benefits, featuredProducts: language === "he" ? "מוצרים מובילים" : language === "ar" ? "منتجات مميزة" : "Featured products", offers: labels.offers, serviceStory: language === "he" ? "שירותים" : language === "ar" ? "الخدمات" : "Service story", roomCards: labels.category, faq: language === "he" ? "שאלות נפוצות" : language === "ar" ? "الأسئلة الشائعة" : "FAQ", contact: labels.contactVisibility };
  const benefitNames: Record<string, string> = language === "he" ? { confidence: "בחירה בטוחה", energy: "יעילות אנרגטית", installation: "תכנון והתקנה", service: "שירות אישי" } : language === "ar" ? { confidence: "اختيار بثقة", energy: "كفاءة الطاقة", installation: "التخطيط والتركيب", service: "خدمة شخصية" } : { confidence: "Confident choices", energy: "Energy efficiency", installation: "Planning & installation", service: "Personal service" };
  const [tab, setTab] = useState<CmsTab>("home");
  const [catalogMode, setCatalogMode] = useState<"products" | "categories" | "brands">("products");
  const [media, setMedia] = useState<MediaAsset[]>([]);
  const [textSearch, setTextSearch] = useState("");
  const [copyGroup, setCopyGroup] = useState("all");
  const [selectedPage, setSelectedPage] = useState<keyof SiteContent["seo"]["pages"]>("home");
  const [notice, setNotice] = useState("");
  const [quickSuccess, setQuickSuccess] = useState("");
  const [quickDraft, setQuickDraft] = useState<QuickProductDraft | null>(null);

  useEffect(() => { void refreshMedia(); }, []);
  useEffect(() => { if (tab === "media") void refreshMedia(); }, [tab]);
  async function refreshMedia() {
    const response = await fetch("/api/admin/media", { cache: "no-store" });
    if (response.ok) setMedia(await response.json() as MediaAsset[]);
  }
  const setPart = <K extends keyof SiteContent>(key: K, next: SiteContent[K]) => onChange({ ...value, [key]: next });
  const upload = async (file?: File) => {
    if (!file) return "";
    const data = new FormData(); data.set("file", file);
    const response = await fetch("/api/admin/media", { method: "POST", body: data });
    const body = await response.json() as { image?: string; error?: string };
    if (!response.ok || !body.image) throw new Error(body.error || "Upload failed");
    await refreshMedia(); return body.image;
  };
  const addMedia = async (setter: (image: string) => void, file?: File) => {
    if (!file) return;
    try { setter(await upload(file)); setNotice(""); } catch (error) { setNotice(error instanceof Error ? error.message : "Upload failed"); }
  };
  const deleteMedia = async (asset: MediaAsset) => {
    if (!asset.deletable || asset.used || JSON.stringify(value).includes(asset.image) || !window.confirm(labels.removeConfirm)) return;
    const response = await fetch("/api/admin/media", { method: "DELETE", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ image: asset.image }) });
    const body = await response.json() as { error?: string };
    if (!response.ok) { setNotice(body.error || labels.used); await refreshMedia(); return; }
    await refreshMedia(); setNotice("");
  };
  const makeQuickProductDraft = (source?: ManagedProduct): QuickProductDraft => {
    const base = source ?? value.products[0] ?? defaultSiteContent.products[0];
    const brandId = source?.brandId ?? value.brands[0]?.id ?? base.brandId;
    const brand = value.brands.find((item) => item.id === brandId);
    const categoryId = source?.categoryId ?? value.categories[0]?.id ?? base.categoryId;
    return {
      ...base,
      id: newStableId("new-model"),
      name: "",
      nameLocalized: blankText(),
      brand: brand?.name.en ?? source?.brand ?? base.brand,
      brandId,
      categoryId,
      price: source ? String(source.price) : "",
      cooling: source ? String(source.cooling) : "",
      previousPrice: source?.previousPrice,
      energy: source?.energy ?? "—",
      image: source?.image ?? "",
      gallery: source ? [...source.gallery] : [],
      socialImage: source?.socialImage && source.socialImage !== source.image ? source.socialImage : "",
      source: source?.source ?? "",
      description: source ? { ...source.description } : {
        he: "מזגן איכותי. פנו אלינו להתאמה לחלל, למחיר ולזמינות.",
        ar: "مكيف هواء. تواصل معنا للتأكد من ملاءمته للمساحة والسعر والتوفر.",
        en: "Air conditioner. Contact us to confirm room suitability, price and availability.",
      },
      warranty: source ? { ...source.warranty } : {
        he: "תנאי האחריות נקבעים לפי היצרן והדגם. יש לאשר את הפרטים בהצעת המחיר.",
        ar: "تخضع تفاصيل الضمان لشروط الشركة المصنعة والموديل؛ يرجى تأكيدها في عرض السعر.",
        en: "Warranty is subject to manufacturer and model terms; confirm details in your quote.",
      },
      seoTitle: source ? { ...source.seoTitle } : blankText(),
      seoDescription: source ? { ...source.seoDescription } : blankText(),
      specs: source ? source.specs.map((row) => [...row] as typeof row) : [],
      features: source ? source.features.map((row) => [...row] as typeof row) : [],
      order: value.products.length + 1,
      available: source?.available ?? true,
      visible: source?.visible ?? true,
      featured: source?.featured ?? false,
    };
  };
  const addProduct = () => { setQuickDraft(makeQuickProductDraft()); setNotice(""); setQuickSuccess(""); };
  const duplicateProduct = (product: ManagedProduct) => { setQuickDraft(makeQuickProductDraft(product)); setNotice(""); setQuickSuccess(""); };
  const commitQuickProduct = () => {
    if (!quickDraft) return;
    const name = quickDraft.name.trim() || quickDraft.nameLocalized.en.trim() || quickDraft.nameLocalized.he.trim() || quickDraft.nameLocalized.ar.trim();
    const canonicalName = quickDraft.nameLocalized.en.trim() || name;
    const brand = value.brands.find((item) => item.id === quickDraft.brandId);
    const price = Number(quickDraft.price);
    const cooling = Number(quickDraft.cooling);
    const hasAllTranslations = (text: LocalizedText) => [text.he, text.ar, text.en].every((entry) => entry.trim().length > 0);
    const incompleteRows = quickDraft.specs.some((row) => row.some((entry) => !entry.trim())) || quickDraft.features.some((row) => row.some((entry) => !entry.trim()));
    if (!name || !hasAllTranslations(quickDraft.nameLocalized) || !hasAllTranslations(quickDraft.description) || !hasAllTranslations(quickDraft.warranty) || !brand || !quickDraft.categoryId || !quickDraft.image || !quickDraft.energy.trim() || !Number.isFinite(price) || price <= 0 || !Number.isFinite(cooling) || cooling <= 0 || incompleteRows) {
      setNotice(quickProductUi[language].required);
      return;
    }
    const product: ManagedProduct = {
      ...quickDraft,
      name: canonicalName,
      nameLocalized: { ...quickDraft.nameLocalized },
      brand: brand.name.en || brand.name[language],
      brandId: brand.id,
      price,
      cooling,
      socialImage: quickDraft.socialImage || quickDraft.image,
      order: value.products.length + 1,
    };
    setPart("products", [...value.products, product]);
    setQuickDraft(null);
    setNotice("");
    setQuickSuccess(quickProductUi[language].copied);
  };
  const addService = () => {
    const item: ManagedService = { id: newStableId("service"), icon: "maintenance", title: { he: "שירות חדש", ar: "خدمة جديدة", en: "New service" }, description: { he: "תיאור השירות", ar: "وصف الخدمة", en: "Service description" }, image: "/images/hero.webp", points: [], priceLabel: { he: "לפי הצעת מחיר", ar: "حسب عرض السعر", en: "Quote on request" }, requestMethod: "contact", order: value.services.length + 1, visible: true };
    setPart("services", [...value.services, item]);
  };
  const addOffer = () => {
    const item: ManagedOffer = { id: newStableId("offer"), title: { he: "מבצע חדש", ar: "عرض جديد", en: "New offer" }, description: blankText(), image: "/images/tadiran.webp", buttonLabel: { he: "לפרטים", ar: "للتفاصيل", en: "Ask for details" }, href: "/contact", productId: "", startsAt: "", endsAt: "", order: value.offers.length + 1, visible: true };
    setPart("offers", [...value.offers, item]);
  };
  const addCategory = () => {
    const item: ManagedCategory = { id: newStableId("category"), name: { he: "קטגוריה חדשה", ar: "تصنيف جديد", en: "New category" }, description: blankText(), image: "/images/tadiran.webp", order: value.categories.length + 1, visible: true };
    setPart("categories", [...value.categories, item]);
  };
  const addBrand = () => {
    const item: ManagedBrand = { id: `brand-${crypto.randomUUID()}`, name: { he: "מותג חדש", ar: "علامة جديدة", en: "New brand" }, logo: "", order: value.brands.length + 1, visible: true };
    setPart("brands", [...value.brands, item]);
  };
  const groups = [...new Set(value.copy.map((entry) => entry.group))];
  const visibleCopy = useMemo(() => value.copy.filter((entry) => (copyGroup === "all" || entry.group === copyGroup) && (!textSearch || `${entry.source} ${entry.he} ${entry.ar} ${entry.en}`.toLowerCase().includes(textSearch.toLowerCase()))), [value.copy, copyGroup, textSearch]);
  const cmsTabs: Array<[CmsTab, string]> = [["home", "home"], ["copy", "copy"], ["catalog", "catalog"], ["services", "services"], ["offers", "offers"], ["about", "about"], ["faq", "faq"], ["links", "links"], ["seo", "seo"], ["appearance", "appearance"], ["media", "media"]];
  const saveButton = <button className="admin-primary-button" disabled={busy} onClick={() => { onSave(value); }}><Save size={16} />{busy ? "…" : labels.save}</button>;
  const deleteButton = (remove: () => void, label = labels.delete) => <button type="button" className="cms-delete" aria-label={label} title={label} onClick={(event) => { event.preventDefault(); event.stopPropagation(); remove(); }}><Trash2 size={16} /></button>;
  const imageField = (label: string, image: string, setter: (image: string) => void) => <div className="cms-image-field"><span>{label}</span><div className="cms-image-box">{image ? <img src={image} alt="" /> : <span>{labels.choose}</span>}<SelectField aria-label={label} value={image} onChange={(event) => setter(event.target.value)}><option value="">{labels.choose}</option>{media.map((asset) => <option key={asset.image} value={asset.image}>{asset.name}</option>)}</SelectField><label className="admin-upload-button"><Upload size={15} />{labels.upload}<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(event) => { void addMedia(setter, event.currentTarget.files?.[0]); event.currentTarget.value = ""; }} /></label></div></div>;
  const galleryField = (product: ManagedProduct) => <div className="cms-repeater"><h3>{galleryLabel}</h3><div className="cms-gallery">{product.gallery.map((image, index) => <div key={`${image}-${index}`}><img src={image} alt=""/><button className="cms-delete" aria-label={labels.delete} onClick={() => setPart("products", value.products.map((item) => item.id === product.id ? { ...item, gallery: item.gallery.filter((_, i) => i !== index) } : item))}><Trash2 size={14}/></button></div>)}</div><div className="cms-gallery-add"><SelectField aria-label={addGalleryImageLabel} value="" onChange={(event) => { const image = event.target.value; if (image && !product.gallery.includes(image)) setPart("products", value.products.map((item) => item.id === product.id ? { ...item, gallery: [...item.gallery, image] } : item)); }}><option value="">{labels.choose}</option>{media.map((asset) => <option key={asset.image} value={asset.image}>{asset.name}</option>)}</SelectField><label className="admin-upload-button"><Upload size={15}/>{labels.upload}<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(event) => { const file = event.currentTarget.files?.[0]; void addMedia((image) => { if (image) setPart("products", value.products.map((item) => item.id === product.id ? { ...item, gallery: [...item.gallery, image] } : item)); }, file); event.currentTarget.value = ""; }}/></label></div></div>;
  const moveButtons = (goUp: () => void, goDown: () => void) => <div className="cms-move"><button onClick={goUp} aria-label={language === "he" ? "העבר מעלה" : language === "ar" ? "تحريك لأعلى" : "Move up"}>↑</button><button onClick={goDown} aria-label={language === "he" ? "העבר מטה" : language === "ar" ? "تحريك لأسفل" : "Move down"}>↓</button></div>;
  const reorder = <T extends { order: number }>(items: T[], index: number, delta: number) => {
    const other = index + delta; if (other < 0 || other >= items.length) return items;
    const result = [...items].sort((a, b) => a.order - b.order); const a = result[index]; const b = result[other]; result[index] = b; result[other] = a; return result.map((item, orderIndex) => ({ ...item, order: orderIndex + 1 }));
  };

  return <div className="cms-root" data-language={language}>
    <div className="cms-intro"><div><span className="admin-eyebrow">{labels[tab]}</span><h2>{labels[tab]}</h2><p>{labels.allControl}</p></div>{saveButton}</div>
    <nav className="cms-tabs" aria-label={labels.content ?? "Content"}>{cmsTabs.map(([id, label]) => <button key={id} className={tab === id ? "active" : ""} onClick={() => setTab(id)}>{labels[label]}</button>)}</nav>
    {notice && <div className="admin-notice error">{notice}</div>}
    {tab === "home" && <div className="cms-stack">
      <Card title={labels.sections}><div className="cms-list">{value.home.sections.slice().sort((a, b) => a.order - b.order).map((section, index) => <div className="cms-row" key={section.id}><Toggle label={sectionNames[section.id] ?? section.id} checked={section.visible} onChange={(visible) => setPart("home", { ...value.home, sections: value.home.sections.map((item) => item.id === section.id ? { ...item, visible } : item) })} />{moveButtons(() => setPart("home", { ...value.home, sections: reorder(value.home.sections, index, -1) }), () => setPart("home", { ...value.home, sections: reorder(value.home.sections, index, 1) }))}</div>)}</div><p className="cms-hint">{labels.sync}</p></Card>
      <Card title={labels.heroLinks}><div className="cms-grid"><Field label={labels.primaryLink} value={value.home.heroPrimaryHref} onChange={(heroPrimaryHref) => setPart("home", { ...value.home, heroPrimaryHref })} /><Field label={labels.secondaryLink} value={value.home.heroSecondaryHref} onChange={(heroSecondaryHref) => setPart("home", { ...value.home, heroSecondaryHref })} /><Toggle label={labels.faqVisibility} checked={value.home.showFaqPreview} onChange={(showFaqPreview) => setPart("home", { ...value.home, showFaqPreview })} /></div></Card>
      <Card title={labels.benefits}><div className="cms-list">{value.home.benefits.slice().sort((a, b) => a.order - b.order).map((benefit, index) => <div className="cms-row" key={benefit.id}><Toggle label={benefitNames[benefit.id] ?? benefit.id} checked={benefit.visible} onChange={(visible) => setPart("home", { ...value.home, benefits: value.home.benefits.map((item) => item.id === benefit.id ? { ...item, visible } : item) })}/>{moveButtons(() => setPart("home", { ...value.home, benefits: reorder(value.home.benefits, index, -1) }), () => setPart("home", { ...value.home, benefits: reorder(value.home.benefits, index, 1) }))}</div>)}</div></Card>
    </div>}
    {tab === "copy" && <Card title={`${labels.copy} · ${visibleCopy.length}`}><div className="cms-filterbar"><label className="cms-search"><Search size={16} /><input aria-label={labels.search} placeholder={labels.search} value={textSearch} onChange={(event) => setTextSearch(event.target.value)} /></label><SelectField aria-label={labels.copyGroup} value={copyGroup} onChange={(event) => setCopyGroup(event.target.value)}><option value="all">{labels.all}</option>{groups.map((group) => <option key={group} value={group}>{pageNames[language][group] ?? group}</option>)}</SelectField></div><div className="cms-copy-list">{visibleCopy.slice(0, 80).map((entry, index) => <details className="cms-copy-item" key={index}><summary className="cms-copy-source"><span>{pageNames[language][entry.group] ?? entry.group}</span><p>{entry.source}</p><span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><LocalizedFields language={language} label={labels.title} value={entry} onChange={(next) => setPart("copy", value.copy.map((item) => item.id === entry.id ? { ...item, ...next } : item))} /></details>)}{visibleCopy.length > 80 && <p className="cms-hint">{language === "he" ? "הצג את 80 התוצאות הראשונות; צמצמו בעזרת חיפוש." : language === "ar" ? "تظهر أول 80 نتيجة؛ استخدم البحث لتضييق النتائج." : "Showing the first 80 results. Narrow the list with search."}</p>}{!visibleCopy.length && <p className="admin-empty">{labels.noMatches}</p>}</div></Card>}
    {tab === "catalog" && <div className="cms-stack">
      <div className="cms-subtabs">{(["products", "categories", "brands"] as const).map((mode) => <button key={mode} className={catalogMode === mode ? "active" : ""} onClick={() => setCatalogMode(mode)}>{mode === "products" ? labels.model : mode === "categories" ? (language === "he" ? "קטגוריות" : language === "ar" ? "التصنيفات" : "Categories") : (language === "he" ? "מותגים" : language === "ar" ? "العلامات" : "Brands")}</button>)}</div>
      {catalogMode === "products" && <Card title={`${labels.catalog} · ${value.products.length}`} action={<button className="admin-primary-button" disabled={!!quickDraft} onClick={addProduct}><Plus size={15} />{labels.add}</button>}>
        {quickSuccess && <p className="cms-product-quick-success" role="status">{quickSuccess}</p>}
        {quickDraft && <section className="cms-product-quick" aria-label={quickProductUi[language].title}>
          <div className="cms-product-quick-head"><div><h3>{quickProductUi[language].title}</h3><p>{quickProductUi[language].hint}</p></div><button type="button" className="cms-quick-cancel" onClick={() => setQuickDraft(null)}>{quickProductUi[language].cancel}</button></div>
          <div className="cms-product-quick-grid">
            <div className="cms-product-quick-name"><LocalizedFields language={language} label={labels.model} value={quickDraft.nameLocalized} onChange={(nameLocalized) => setQuickDraft((current) => current ? { ...current, name: nameLocalized.en || nameLocalized.he || nameLocalized.ar, nameLocalized } : current)} /></div>
            <label className="cms-field"><span>{labels.brand}</span><SelectField value={quickDraft.brandId} onChange={(event) => { const brand = value.brands.find((item) => item.id === event.target.value); setQuickDraft({ ...quickDraft, brandId: event.target.value, brand: brand?.name.en ?? "" }); }}><option value="">{labels.select}</option>{value.brands.map((brand) => <option key={brand.id} value={brand.id}>{brand.name[language]}</option>)}</SelectField></label>
            <Field label={labels.price} value={quickDraft.price} type="number" onChange={(price) => setQuickDraft({ ...quickDraft, price })} />
            <Field label={labels.cooling} value={quickDraft.cooling} type="number" onChange={(cooling) => setQuickDraft({ ...quickDraft, cooling })} />
            <label className="cms-field"><span>{categoryLabel}</span><SelectField value={quickDraft.categoryId} onChange={(event) => { const categoryId = event.target.value; setQuickDraft({ ...quickDraft, categoryId, ...(roomCategoryIds.has(categoryId) ? { room: categoryId as ManagedProduct["room"] } : {}) }); }}><option value="">{labels.select}</option>{value.categories.map((category) => <option key={category.id} value={category.id}>{category.name[language]}</option>)}</SelectField></label>
          </div>
          <div className="cms-product-quick-image">{imageField(mainImageLabel, quickDraft.image, (image) => setQuickDraft((current) => current ? { ...current, image } : current))}</div>
          <section className="cms-product-quick-section">
            <h4>{quickProductUi[language].content}</h4>
            <LocalizedFields language={language} label={labels.description} value={quickDraft.description} multiline onChange={(description) => setQuickDraft((current) => current ? { ...current, description } : current)} />
            <LocalizedFields language={language} label={labels.warranty} value={quickDraft.warranty} multiline onChange={(warranty) => setQuickDraft((current) => current ? { ...current, warranty } : current)} />
          </section>
          <section className="cms-product-quick-section">
            <h4>{quickProductUi[language].specsFeatures}</h4>
            <div className="cms-repeater cms-product-quick-specs"><h5>{labels.specifications}</h5><ProductRowsEditor kind="specs" rows={quickDraft.specs} language={language} labels={labels} onChange={(specs) => setQuickDraft((current) => current ? { ...current, specs: specs as ManagedProduct["specs"] } : current)} /></div>
            <div className="cms-repeater cms-product-quick-features"><h5>{labels.features}</h5><ProductRowsEditor kind="features" rows={quickDraft.features} language={language} labels={labels} onChange={(features) => setQuickDraft((current) => current ? { ...current, features: features as ManagedProduct["features"] } : current)} /></div>
          </section>
          <section className="cms-product-quick-section">
            <h4>{quickProductUi[language].mediaSeo}</h4>
            <div className="cms-product-quick-gallery"><h5>{galleryLabel}</h5><div className="cms-gallery">{quickDraft.gallery.map((image, index) => <div key={`${image}-${index}`}><img src={image} alt="" /><button type="button" className="cms-delete" aria-label={labels.delete} onClick={() => setQuickDraft((current) => current ? { ...current, gallery: current.gallery.filter((_, sourceIndex) => sourceIndex !== index) } : current)}><Trash2 size={14} /></button></div>)}</div><div className="cms-gallery-add"><SelectField aria-label={addGalleryImageLabel} value="" onChange={(event) => { const image = event.target.value; if (image && !quickDraft.gallery.includes(image)) setQuickDraft((current) => current ? { ...current, gallery: [...current.gallery, image] } : current); }}><option value="">{labels.choose}</option>{media.map((asset) => <option key={asset.image} value={asset.image}>{asset.name}</option>)}</SelectField><label className="admin-upload-button"><Upload size={15} />{labels.upload}<input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(event) => { const file = event.currentTarget.files?.[0]; void addMedia((image) => { if (image) setQuickDraft((current) => current ? { ...current, gallery: [...current.gallery, image] } : current); }, file); event.currentTarget.value = ""; }} /></label></div></div>
            {imageField(productShareLabel, quickDraft.socialImage === quickDraft.image ? "" : quickDraft.socialImage, (socialImage) => setQuickDraft((current) => current ? { ...current, socialImage } : current))}
            <LocalizedFields language={language} label={labels.seoTitle} value={quickDraft.seoTitle} onChange={(seoTitle) => setQuickDraft((current) => current ? { ...current, seoTitle } : current)} />
            <LocalizedFields language={language} label={labels.seoDescription} value={quickDraft.seoDescription} multiline onChange={(seoDescription) => setQuickDraft((current) => current ? { ...current, seoDescription } : current)} />
          </section>
          <section className="cms-product-quick-section">
            <h4>{quickProductUi[language].settings}</h4>
            <div className="cms-grid"><div className="cms-product-id"><Field label={labels.id} value={quickDraft.id} onChange={(id) => setQuickDraft((current) => current ? { ...current, id: safeId(id) } : current)} /></div><Field label={labels.oldPrice} value={quickDraft.previousPrice ?? ""} type="number" onChange={(raw) => setQuickDraft((current) => current ? { ...current, previousPrice: raw ? Number(raw) : undefined } : current)} /><Field label={labels.energy} value={quickDraft.energy} onChange={(energy) => setQuickDraft((current) => current ? { ...current, energy } : current)} />{!roomCategoryIds.has(quickDraft.categoryId) && <label className="cms-field"><span>{roomLabel}</span><SelectField value={quickDraft.room} onChange={(event) => setQuickDraft((current) => current ? { ...current, room: event.target.value as ManagedProduct["room"] } : current)}><option value="bedroom">{roomNames[0]}</option><option value="living">{roomNames[1]}</option><option value="large">{roomNames[2]}</option></SelectField></label>}<Field label={labels.source} value={quickDraft.source} onChange={(source) => setQuickDraft((current) => current ? { ...current, source } : current)} /><Field label={labels.order} value={quickDraft.order} type="number" onChange={(raw) => setQuickDraft((current) => current ? { ...current, order: Number(raw) } : current)} /></div>
            <Toggle label={labels.available} checked={quickDraft.available} onChange={(available) => setQuickDraft((current) => current ? { ...current, available } : current)} />
            <Toggle label={labels.visible} checked={quickDraft.visible} onChange={(visible) => setQuickDraft((current) => current ? { ...current, visible } : current)} />
            <Toggle label={labels.featured} checked={quickDraft.featured} onChange={(featured) => setQuickDraft((current) => current ? { ...current, featured } : current)} />
          </section>
          {notice && <p className="cms-product-quick-notice" role="status">{notice}</p>}
          <div className="cms-product-quick-actions"><button type="button" className="admin-primary-button" disabled={busy} onClick={commitQuickProduct}><Plus size={15} />{quickProductUi[language].add}</button><button type="button" className="cms-quick-cancel" onClick={() => setQuickDraft(null)}>{quickProductUi[language].cancel}</button></div>
        </section>}
        <div className="cms-list">{value.products.slice().sort((a, b) => a.order - b.order).map((product, index) => {
          const productIndex = value.products.indexOf(product);
          const updateProduct = (changes: Partial<ManagedProduct>) => setPart("products", value.products.map((item, sourceIndex) => sourceIndex === productIndex ? { ...item, ...changes } : item));
          const updateProductId = (rawId: string) => {
            const id = safeId(rawId);
            const ambiguousId = value.products.some((item, sourceIndex) => sourceIndex !== productIndex && item.id === product.id);
            onChange({ ...value, products: value.products.map((item, sourceIndex) => sourceIndex === productIndex ? { ...item, id } : item), offers: ambiguousId ? value.offers : value.offers.map((offer) => offer.productId === product.id ? { ...offer, productId: id } : offer) });
          };
          return <details className="cms-entity" key={`${product.id}-${productIndex}`}>
            <summary className="cms-entity-title"><img src={product.image} alt=""/><div><b>{product.nameLocalized[language] || product.name}</b><small>{product.brand} · ₪{product.price.toLocaleString("en-IL")}</small></div><button type="button" className="cms-copy-product" aria-label={quickProductUi[language].copy} title={quickProductUi[language].copy} disabled={!!quickDraft} onClick={(event) => { event.preventDefault(); event.stopPropagation(); duplicateProduct(product); }}><Copy size={15}/></button>{deleteButton(() => { if (window.confirm(labels.removeConfirm)) { const products = value.products.filter((item) => item.id !== product.id); onChange({ ...value, products, offers: value.offers.map((offer) => offer.productId === product.id ? { ...offer, productId: "" } : offer) }); } })}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary>
            <div className="cms-entity-body cms-product-editor-body">
              <div className="cms-product-core">
                <LocalizedFields language={language} label={labels.model} value={product.nameLocalized} onChange={(nameLocalized) => updateProduct({ nameLocalized, name: nameLocalized.en || nameLocalized.he || nameLocalized.ar })} />
                <div className="cms-grid">
                  <label className="cms-field"><span>{labels.brand}</span><SelectField value={product.brandId} onChange={(event) => { const brand = value.brands.find((entry) => entry.id === event.target.value); updateProduct({ brandId: event.target.value, brand: brand?.name.en ?? product.brand }); }}><option value="">{labels.select}</option>{value.brands.map((brand) => <option key={brand.id} value={brand.id}>{brand.name[language]}</option>)}</SelectField></label>
                  <label className="cms-field"><span>{categoryLabel}</span><SelectField value={product.categoryId} onChange={(event) => { const categoryId = event.target.value; updateProduct({ categoryId, ...(roomCategoryIds.has(categoryId) ? { room: categoryId as ManagedProduct["room"] } : {}) }); }}><option value="">{labels.select}</option>{value.categories.map((category) => <option key={category.id} value={category.id}>{category.name[language]}</option>)}</SelectField></label>
                  <Field label={labels.price} value={product.price} type="number" onChange={(raw) => updateProduct({ price: Number(raw) })} />
                  <Field label={labels.cooling} value={product.cooling} type="number" onChange={(raw) => updateProduct({ cooling: Number(raw) })} />
                </div>
                {imageField(mainImageLabel, product.image, (image) => updateProduct({ image, socialImage: !product.socialImage || product.socialImage === product.image ? image : product.socialImage }))}
                <Toggle label={labels.available} checked={product.available} onChange={(available) => updateProduct({ available })} />
              </div>
              <details className="cms-product-extra" data-cms-product-section="advanced"><summary><span>{quickProductUi[language].more}</span><small>{labels.specifications}, SEO, {labels.warranty}</small><ChevronDown size={15}/></summary><div className="cms-product-extra-body">
                <div className="cms-product-id"><Field label={labels.id} value={product.id} onChange={updateProductId} /></div>
                <div className="cms-grid"><Field label={labels.oldPrice} value={product.previousPrice ?? ""} type="number" onChange={(raw) => updateProduct({ previousPrice: raw ? Number(raw) : undefined })} /><Field label={labels.energy} value={product.energy} onChange={(energy) => updateProduct({ energy })} />{!roomCategoryIds.has(product.categoryId) && <label className="cms-field"><span>{roomLabel}</span><SelectField value={product.room} onChange={(event) => updateProduct({ room: event.target.value as ManagedProduct["room"] })}><option value="bedroom">{roomNames[0]}</option><option value="living">{roomNames[1]}</option><option value="large">{roomNames[2]}</option></SelectField></label>}<Field label={labels.source} value={product.source} onChange={(source) => updateProduct({ source })} /><Field label={labels.order} value={product.order} type="number" onChange={(raw) => updateProduct({ order: Number(raw) })} /><Toggle label={labels.visible} checked={product.visible} onChange={(visible) => updateProduct({ visible })} /><Toggle label={labels.featured} checked={product.featured} onChange={(featured) => updateProduct({ featured })} /></div>
                <details className="cms-product-extra"><summary><span>{labels.description} &amp; {labels.warranty}</span><ChevronDown size={14}/></summary><div className="cms-product-extra-body"><LocalizedFields language={language} label={labels.description} value={product.description} multiline onChange={(description) => updateProduct({ description })} /><LocalizedFields language={language} label={labels.warranty} value={product.warranty} multiline onChange={(warranty) => updateProduct({ warranty })} /></div></details>
                {galleryField(product)}
                {imageField(productShareLabel, product.socialImage === product.image ? "" : product.socialImage, (socialImage) => updateProduct({ socialImage }))}
                <LocalizedFields language={language} label={labels.seoTitle} value={product.seoTitle} onChange={(seoTitle) => updateProduct({ seoTitle })} />
                <LocalizedFields language={language} label={labels.seoDescription} value={product.seoDescription} multiline onChange={(seoDescription) => updateProduct({ seoDescription })} />
                <div className="cms-repeater cms-product-specs"><h3>{labels.specifications}</h3><ProductRowsEditor kind="specs" rows={product.specs} language={language} labels={labels} onChange={(specs) => updateProduct({ specs: specs as ManagedProduct["specs"] })} /></div>
                <div className="cms-repeater cms-product-features"><h3>{labels.features}</h3><ProductRowsEditor kind="features" rows={product.features} language={language} labels={labels} onChange={(features) => updateProduct({ features: features as ManagedProduct["features"] })} /></div>
              </div></details>
            </div>
            <div className="cms-row cms-entity-bottom">{moveButtons(() => setPart("products", reorder(value.products, index, -1)), () => setPart("products", reorder(value.products, index, 1)))}</div>
          </details>;
        })}</div>
      </Card>}
      {catalogMode === "categories" && <Card title={labels.category} action={<button className="admin-primary-button" onClick={addCategory}><Plus size={15} />{labels.add}</button>}><div className="cms-list">{value.categories.slice().sort((a, b) => a.order - b.order).map((item, index) => <details className="cms-entity" key={index}><summary className="cms-entity-title"><b>{item.name[language]}</b>{deleteButton(() => { if (value.products.some((product) => product.categoryId === item.id)) { setNotice(language === "he" ? "העבירו קודם את המוצרים לקטגוריה אחרת." : language === "ar" ? "انقل المنتجات إلى تصنيف آخر أولًا." : "Reassign products to another category first."); return; } if (window.confirm(labels.removeConfirm)) setPart("categories", value.categories.filter((entry, index) => index !== value.categories.indexOf(item))); })}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><Field label={labels.id} value={item.id} onChange={(id) => { const nextId = safeId(id); const categoryIndex = value.categories.indexOf(item); const ambiguousId = value.categories.some((entry, index) => index !== categoryIndex && entry.id === item.id); onChange({ ...value, categories: value.categories.map((entry, index) => index === categoryIndex ? { ...entry, id: nextId } : entry), products: ambiguousId ? value.products : value.products.map((product) => product.categoryId === item.id ? { ...product, categoryId: nextId } : product) }); }} /><LocalizedFields language={language} label={labels.name} value={item.name} onChange={(name) => setPart("categories", value.categories.map((entry) => entry.id === item.id ? { ...entry, name } : entry))} /><LocalizedFields language={language} label={labels.description} value={item.description} multiline onChange={(description) => setPart("categories", value.categories.map((entry) => entry.id === item.id ? { ...entry, description } : entry))} />{imageField(labels.image, item.image, (image) => setPart("categories", value.categories.map((entry) => entry.id === item.id ? { ...entry, image } : entry)))}<div className="cms-grid"><Field label={labels.order} value={item.order} type="number" onChange={(raw) => setPart("categories", value.categories.map((entry) => entry.id === item.id ? { ...entry, order: Number(raw) } : entry))} /><Toggle label={labels.visible} checked={item.visible} onChange={(visible) => setPart("categories", value.categories.map((entry) => entry.id === item.id ? { ...entry, visible } : entry))} /></div></div><div className="cms-entity-bottom">{moveButtons(() => setPart("categories", reorder(value.categories, index, -1)), () => setPart("categories", reorder(value.categories, index, 1)))}</div></details>)}</div></Card>}
      {catalogMode === "brands" && <Card title={labels.brand} action={<button className="admin-primary-button" onClick={addBrand}><Plus size={15} />{labels.add}</button>}><div className="cms-list">{value.brands.slice().sort((a, b) => a.order - b.order).map((item, index) => {
        const brandIndex = value.brands.indexOf(item);
        const updateBrand = (changes: Partial<ManagedBrand>) => setPart("brands", value.brands.map((entry, sourceIndex) => sourceIndex === brandIndex ? { ...entry, ...changes } : entry));
        const updateBrandId = (rawId: string) => {
          const nextId = safeId(rawId);
          const ambiguousId = value.brands.some((entry, sourceIndex) => sourceIndex !== brandIndex && entry.id === item.id);
          onChange({
            ...value,
            brands: value.brands.map((entry, sourceIndex) => sourceIndex === brandIndex ? { ...entry, id: nextId } : entry),
            products: ambiguousId ? value.products : value.products.map((product) => product.brandId === item.id ? { ...product, brandId: nextId } : product),
          });
        };
        return <details className="cms-entity" key={index}>
          <summary className="cms-entity-title"><b>{item.name[language]}</b>{deleteButton(() => { if (value.products.some((product) => product.brandId === item.id)) { setNotice(language === "he" ? "העבירו קודם את המוצרים למותג אחר." : language === "ar" ? "انقل المنتجات إلى علامة أخرى أولًا." : "Reassign products to another brand first."); return; } if (window.confirm(labels.removeConfirm)) setPart("brands", value.brands.filter((_, sourceIndex) => sourceIndex !== brandIndex)); })}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary>
          <div className="cms-entity-body"><Field label={labels.id} value={item.id} onChange={updateBrandId} /><LocalizedFields language={language} label={labels.name} value={item.name} onChange={(name) => updateBrand({ name })} />{imageField(labels.image, item.logo, (logo) => updateBrand({ logo }))}<div className="cms-grid"><Field label={labels.order} value={item.order} type="number" onChange={(raw) => updateBrand({ order: Number(raw) })} /><Toggle label={labels.visible} checked={item.visible} onChange={(visible) => updateBrand({ visible })} /></div></div>
          <div className="cms-entity-bottom">{moveButtons(() => setPart("brands", reorder(value.brands, index, -1)), () => setPart("brands", reorder(value.brands, index, 1)))}</div>
        </details>;
      })}</div></Card>}
    </div>}
    {tab === "services" && <Card title={labels.services} action={<button className="admin-primary-button" onClick={addService}><Plus size={15} />{labels.add}</button>}><div className="cms-list">{value.services.slice().sort((a, b) => a.order - b.order).map((service, index) => <details className="cms-entity" key={index}><summary className="cms-entity-title"><b>{service.title[language]}</b>{deleteButton(() => { if (window.confirm(labels.removeConfirm)) setPart("services", value.services.filter((item, sourceIndex) => sourceIndex !== value.services.indexOf(service))); })}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><Field label={labels.id} value={service.id} onChange={(id) => { const serviceIndex = value.services.indexOf(service); setPart("services", value.services.map((item, index) => index === serviceIndex ? { ...item, id: safeId(id) } : item)); }} /><LocalizedFields language={language} label={labels.title} value={service.title} onChange={(title) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, title } : item))} /><LocalizedFields language={language} label={labels.description} value={service.description} multiline onChange={(description) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, description } : item))} /><LocalizedFields language={language} label={labels.price} value={service.priceLabel} onChange={(priceLabel) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, priceLabel } : item))} />{imageField(labels.serviceImage, service.image, (image) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, image } : item)))}<div className="cms-grid"><label className="cms-field"><span>{labels.icon}</span><SelectField value={service.icon} onChange={(event) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, icon: event.target.value as ManagedService["icon"] } : item))}>{(["installation", "maintenance", "repair", "consultation"] as const).map((icon) => <option key={icon} value={icon}>{icon}</option>)}</SelectField></label><label className="cms-field"><span>{labels.method}</span><SelectField value={service.requestMethod} onChange={(event) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, requestMethod: event.target.value as ManagedService["requestMethod"] } : item))}><option value="contact">{labels.methodContact}</option><option value="phone">{labels.methodPhone}</option><option value="whatsapp">{labels.methodWhatsapp}</option></SelectField></label><Field label={labels.order} value={service.order} type="number" onChange={(raw) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, order: Number(raw) } : item))} /><Toggle label={labels.visible} checked={service.visible} onChange={(visible) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, visible } : item))} /></div><div className="cms-repeater"><h3>{labels.point}</h3>{service.points.map((point, pointIndex) => <div key={pointIndex} className="cms-repeater-row"><LocalizedFields language={language} label={`${labels.point} ${pointIndex + 1}`} value={point} onChange={(next) => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, points: item.points.map((entry, i) => i === pointIndex ? next : entry) } : item))} />{deleteButton(() => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, points: item.points.filter((_, i) => i !== pointIndex) } : item)))}</div>)}<button className="cms-add-row" onClick={() => setPart("services", value.services.map((item) => item.id === service.id ? { ...item, points: [...item.points, promptText()] } : item))}><Plus size={14} />{labels.addPoint}</button></div></div><div className="cms-entity-bottom">{moveButtons(() => setPart("services", reorder(value.services, index, -1)), () => setPart("services", reorder(value.services, index, 1)))}</div></details>)}</div><Card title={labels.process}><div className="cms-list">{value.servicePage.process.map((step, index) => <details className="cms-entity" key={index}><summary className="cms-entity-title"><b>{step.title[language]}</b>{deleteButton(() => setPart("servicePage", { ...value.servicePage, process: value.servicePage.process.filter((item, index) => index !== value.servicePage.process.indexOf(step)) }))}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><LocalizedFields language={language} label={labels.title} value={step.title} onChange={(title) => setPart("servicePage", { ...value.servicePage, process: value.servicePage.process.map((item, index) => index === value.servicePage.process.indexOf(step) ? { ...item, title } : item) })} /><LocalizedFields language={language} label={labels.description} value={step.description} multiline onChange={(description) => setPart("servicePage", { ...value.servicePage, process: value.servicePage.process.map((item, index) => index === value.servicePage.process.indexOf(step) ? { ...item, description } : item) })} /><Toggle label={labels.visible} checked={step.visible} onChange={(visible) => setPart("servicePage", { ...value.servicePage, process: value.servicePage.process.map((item, index) => index === value.servicePage.process.indexOf(step) ? { ...item, visible } : item) })} /></div></details>)}</div><button className="cms-add-row" onClick={() => setPart("servicePage", { ...value.servicePage, process: [...value.servicePage.process, { id: newStableId("step"), title: promptText(), description: promptText(), order: value.servicePage.process.length + 1, visible: true }] })}><Plus size={14} />{labels.add}</button><div className="cms-grid"><Toggle label={labels.processVisibility} checked={value.servicePage.showContact} onChange={(showContact) => setPart("servicePage", { ...value.servicePage, showContact })} /><Toggle label={labels.faqVisibility} checked={value.servicePage.showFaq} onChange={(showFaq) => setPart("servicePage", { ...value.servicePage, showFaq })} /></div></Card></Card>}
    {tab === "offers" && <Card title={labels.offers} action={<button className="admin-primary-button" onClick={addOffer}><Plus size={15} />{labels.add}</button>}><div className="cms-list">{value.offers.slice().sort((a, b) => a.order - b.order).map((offer, index) => <details className="cms-entity" key={index}><summary className="cms-entity-title"><b>{offer.title[language]}</b>{deleteButton(() => { if (window.confirm(labels.removeConfirm)) setPart("offers", value.offers.filter((item, sourceIndex) => sourceIndex !== value.offers.indexOf(offer))); })}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><Field label={labels.id} value={offer.id} onChange={(id) => { const offerIndex = value.offers.indexOf(offer); setPart("offers", value.offers.map((item, index) => index === offerIndex ? { ...item, id: safeId(id) } : item)); }} /><LocalizedFields language={language} label={labels.title} value={offer.title} onChange={(title) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, title } : item))} /><LocalizedFields language={language} label={labels.description} value={offer.description} multiline onChange={(description) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, description } : item))} /><LocalizedFields language={language} label={labels.button} value={offer.buttonLabel} onChange={(buttonLabel) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, buttonLabel } : item))} />{imageField(labels.image, offer.image, (image) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, image } : item)))}<div className="cms-grid"><Field label={labels.price} value={offer.price ?? ""} type="number" onChange={(raw) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, price: raw ? Number(raw) : undefined } : item))} /><Field label={labels.oldPrice} value={offer.oldPrice ?? ""} type="number" onChange={(raw) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, oldPrice: raw ? Number(raw) : undefined } : item))} /><Field label={labels.start} value={offer.startsAt} type="date" onChange={(startsAt) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, startsAt } : item))} /><Field label={labels.end} value={offer.endsAt} type="date" onChange={(endsAt) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, endsAt } : item))} /><label className="cms-field"><span>{labels.product}</span><SelectField value={offer.productId} onChange={(event) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, productId: event.target.value } : item))}><option value="">{labels.noProduct}</option>{value.products.map((product) => <option key={product.id} value={product.id}>{product.nameLocalized[language]}</option>)}</SelectField></label><Field label={labels.href} value={offer.href} onChange={(href) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, href } : item))} /><Field label={labels.order} value={offer.order} type="number" onChange={(raw) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, order: Number(raw) } : item))} /><Toggle label={labels.visible} checked={offer.visible} onChange={(visible) => setPart("offers", value.offers.map((item) => item.id === offer.id ? { ...item, visible } : item))} /></div></div><div className="cms-entity-bottom">{moveButtons(() => setPart("offers", reorder(value.offers, index, -1)), () => setPart("offers", reorder(value.offers, index, 1)))}</div></details>)}</div></Card>}
    {tab === "about" && <div className="cms-stack"><Card title={labels.aboutImage}>{imageField(labels.aboutImage, value.about.storyImage, (storyImage) => setPart("about", { ...value.about, storyImage }))}</Card><Card title={labels.value} action={<button className="admin-primary-button" onClick={() => setPart("about", { ...value.about, values: [...value.about.values, { id: newStableId("value"), icon: "fit", title: promptText(), description: promptText(), order: value.about.values.length + 1, visible: true }] })}><Plus size={15} />{labels.add}</button>}><div className="cms-list">{value.about.values.map((item, index) => <details className="cms-entity" key={index}><summary className="cms-entity-title"><b>{item.title[language]}</b>{deleteButton(() => setPart("about", { ...value.about, values: value.about.values.filter((entry, index) => index !== value.about.values.indexOf(item)) }))}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><Field label={labels.id} value={item.id} onChange={(id) => setPart("about", { ...value.about, values: value.about.values.map((entry, index) => index === value.about.values.indexOf(item) ? { ...entry, id: safeId(id) } : entry) })} /><label className="cms-field"><span>{labels.icon}</span><SelectField value={item.icon} onChange={(event) => setPart("about", { ...value.about, values: value.about.values.map((entry) => entry.id === item.id ? { ...entry, icon: event.target.value as typeof item.icon } : entry) })}><option value="fit">Fit</option><option value="craft">Craft</option><option value="communication">Communication</option></SelectField></label><LocalizedFields language={language} label={labels.title} value={item.title} onChange={(title) => setPart("about", { ...value.about, values: value.about.values.map((entry) => entry.id === item.id ? { ...entry, title } : entry) })} /><LocalizedFields language={language} label={labels.description} value={item.description} multiline onChange={(description) => setPart("about", { ...value.about, values: value.about.values.map((entry) => entry.id === item.id ? { ...entry, description } : entry) })} /><Field label={labels.order} value={item.order} type="number" onChange={(raw) => setPart("about", { ...value.about, values: value.about.values.map((entry) => entry.id === item.id ? { ...entry, order: Number(raw) } : entry) })} /><Toggle label={labels.visible} checked={item.visible} onChange={(visible) => setPart("about", { ...value.about, values: value.about.values.map((entry) => entry.id === item.id ? { ...entry, visible } : entry) })} /></div></details>)}</div></Card></div>}
    {tab === "faq" && <div className="cms-stack"><Card title={labels.question} action={<button className="admin-primary-button" onClick={() => setPart("faqs", [...value.faqs, { id: newStableId("faq"), question: promptText(), answer: promptText(), order: value.faqs.length + 1, visible: true }])}><Plus size={15} />{labels.add}</button>}><div className="cms-list">{value.faqs.map((item, index) => <details className="cms-entity" key={index}><summary className="cms-entity-title"><b>{item.question[language]}</b>{deleteButton(() => setPart("faqs", value.faqs.filter((entry, index) => index !== value.faqs.indexOf(item))))}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><Field label={labels.id} value={item.id} onChange={(id) => setPart("faqs", value.faqs.map((entry, index) => index === value.faqs.indexOf(item) ? { ...entry, id: safeId(id) } : entry))} /><LocalizedFields language={language} label={labels.question} value={item.question} onChange={(question) => setPart("faqs", value.faqs.map((entry) => entry.id === item.id ? { ...entry, question } : entry))} /><LocalizedFields language={language} label={labels.answer} value={item.answer} multiline onChange={(answer) => setPart("faqs", value.faqs.map((entry) => entry.id === item.id ? { ...entry, answer } : entry))} /><Toggle label={labels.visible} checked={item.visible} onChange={(visible) => setPart("faqs", value.faqs.map((entry) => entry.id === item.id ? { ...entry, visible } : entry))} /></div></details>)}</div></Card><Card title={labels.policy} action={<button className="admin-primary-button" onClick={() => setPart("policies", { ...value.policies, items: [...value.policies.items, { id: newStableId("policy"), title: promptText(), body: promptText(), order: value.policies.items.length + 1, visible: true }] })}><Plus size={15} />{labels.add}</button>}><LocalizedFields language={language} label={labels.description} value={value.policies.notice} onChange={(notice) => setPart("policies", { ...value.policies, notice })} /><div className="cms-list">{value.policies.items.map((item, index) => <details className="cms-entity" key={index}><summary className="cms-entity-title"><b>{item.title[language]}</b>{deleteButton(() => setPart("policies", { ...value.policies, items: value.policies.items.filter((entry, index) => index !== value.policies.items.indexOf(item)) }))}<span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><Field label={labels.id} value={item.id} onChange={(id) => setPart("policies", { ...value.policies, items: value.policies.items.map((entry, index) => index === value.policies.items.indexOf(item) ? { ...entry, id: safeId(id) } : entry) })} /><LocalizedFields language={language} label={labels.title} value={item.title} onChange={(title) => setPart("policies", { ...value.policies, items: value.policies.items.map((entry) => entry.id === item.id ? { ...entry, title } : entry) })} /><LocalizedFields language={language} label={labels.body} value={item.body} multiline onChange={(body) => setPart("policies", { ...value.policies, items: value.policies.items.map((entry) => entry.id === item.id ? { ...entry, body } : entry) })} /><Toggle label={labels.visible} checked={item.visible} onChange={(visible) => setPart("policies", { ...value.policies, items: value.policies.items.map((entry) => entry.id === item.id ? { ...entry, visible } : entry) })} /></div></details>)}</div></Card><Card title={labels.faqVisibility}><div className="cms-grid"><Toggle label={labels.home} checked={value.faqPage.showOnHome} onChange={(showOnHome) => setPart("faqPage", { ...value.faqPage, showOnHome })} /><Toggle label={labels.services} checked={value.faqPage.showOnServices} onChange={(showOnServices) => setPart("faqPage", { ...value.faqPage, showOnServices })} /><Toggle label={labels.contactVisibility} checked={value.faqPage.showContact} onChange={(showContact) => setPart("faqPage", { ...value.faqPage, showContact })} /></div></Card></div>}
    {tab === "links" && <div className="cms-stack"><Card title={labels.image}><div className="cms-grid">{imageField(language === "he" ? "Company logo" : language === "ar" ? "Company logo" : "Company logo", value.settings.logoImage, (logoImage) => setPart("settings", { ...value.settings, logoImage }))}{imageField(language === "he" ? "Homepage hero image" : language === "ar" ? "Homepage hero image" : "Homepage hero image", value.settings.heroImage, (heroImage) => setPart("settings", { ...value.settings, heroImage }))}</div></Card><Card title={labels.company}><div className="cms-grid"><LocalizedFields language={language} label={labels.company} value={value.settings.companyName} onChange={(companyName) => setPart("settings", { ...value.settings, companyName })} /><LocalizedFields language={language} label={labels.descriptor} value={value.settings.brandDescriptor} onChange={(brandDescriptor) => setPart("settings", { ...value.settings, brandDescriptor })} /><LocalizedFields language={language} label={labels.topbar} value={value.settings.topbarMessage} onChange={(topbarMessage) => setPart("settings", { ...value.settings, topbarMessage })} /><Field label={labels.phone} value={value.settings.phoneDisplay} onChange={(phoneDisplay) => setPart("settings", { ...value.settings, phoneDisplay })} /><Field label={labels.phoneIntl} value={value.settings.phoneE164} dir="ltr" onChange={(phoneE164) => setPart("settings", { ...value.settings, phoneE164: `+${phoneE164.replace(/\D/g, "")}` })} /><Field label={labels.whatsapp} value={value.settings.whatsappE164} dir="ltr" onChange={(whatsappE164) => setPart("settings", { ...value.settings, whatsappE164: `+${whatsappE164.replace(/\D/g, "")}` })} /><Field label={labels.email} value={value.settings.email} type="email" onChange={(email) => setPart("settings", { ...value.settings, email })} /><LocalizedFields language={language} label={labels.address} value={value.settings.address} onChange={(address) => setPart("settings", { ...value.settings, address })} /><LocalizedFields language={language} label={labels.hours} value={value.settings.businessHours} onChange={(businessHours) => setPart("settings", { ...value.settings, businessHours })} /><Field label={labels.areaHe} value={value.settings.serviceAreaHe} onChange={(serviceAreaHe) => setPart("settings", { ...value.settings, serviceAreaHe })} /><Field label={labels.areaAr} value={value.settings.serviceAreaAr} onChange={(serviceAreaAr) => setPart("settings", { ...value.settings, serviceAreaAr })} /><Field label={labels.areaEn} value={value.settings.serviceAreaEn} onChange={(serviceAreaEn) => setPart("settings", { ...value.settings, serviceAreaEn })} /><Field label={labels.href} value={value.settings.headerCtaHref} onChange={(headerCtaHref) => setPart("settings", { ...value.settings, headerCtaHref })} /><Toggle label={labels.indicative} checked={value.settings.pricesAreIndicative} onChange={(pricesAreIndicative) => setPart("settings", { ...value.settings, pricesAreIndicative })} /></div></Card>
      <Card title={labels.nav}><div className="cms-list">{value.navigation.map((item, index) => <LinkEditor key={index} item={item} language={language} labels={labels} onChange={(next) => setPart("navigation", value.navigation.map((entry, sourceIndex) => sourceIndex === index ? next : entry))} onDelete={() => setPart("navigation", value.navigation.filter((_, sourceIndex) => sourceIndex !== index))} />)}</div><button className="cms-add-row" onClick={() => setPart("navigation", [...value.navigation, { id: newStableId("nav"), label: promptText(), href: "/", order: value.navigation.length + 1, visible: true }])}><Plus size={14} />{labels.add}</button></Card>
      <Card title={labels.footer}><div className="cms-list">{value.footer.links.map((item, index) => <LinkEditor key={index} item={item} language={language} labels={labels} onChange={(next) => setPart("footer", { links: value.footer.links.map((entry, sourceIndex) => sourceIndex === index ? next : entry) })} onDelete={() => setPart("footer", { links: value.footer.links.filter((_, sourceIndex) => sourceIndex !== index) })} />)}</div><button className="cms-add-row" onClick={() => setPart("footer", { links: [...value.footer.links, { id: newStableId("footer"), label: promptText(), href: "/", order: value.footer.links.length + 1, visible: true }] })}><Plus size={14} />{labels.add}</button></Card>
      <Card title={labels.instagram}><div className="cms-list">{value.settings.socialLinks.map((item, index) => <details className="cms-entity" key={index}><summary className="cms-entity-title"><b>{item.label}</b><span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><div className="cms-grid"><Field label={labels.name} value={item.label} onChange={(label) => setPart("settings", { ...value.settings, socialLinks: value.settings.socialLinks.map((entry, sourceIndex) => sourceIndex === index ? { ...entry, label } : entry) })} /><Field label={labels.href} value={item.url} onChange={(url) => setPart("settings", { ...value.settings, socialLinks: value.settings.socialLinks.map((entry, sourceIndex) => sourceIndex === index ? { ...entry, url } : entry) })} /><Toggle label={labels.visible} checked={item.visible} onChange={(visible) => setPart("settings", { ...value.settings, socialLinks: value.settings.socialLinks.map((entry, sourceIndex) => sourceIndex === index ? { ...entry, visible } : entry) })} />{deleteButton(() => setPart("settings", { ...value.settings, socialLinks: value.settings.socialLinks.filter((_, sourceIndex) => sourceIndex !== index) }))}</div></div></details>)}</div><button className="cms-add-row" onClick={() => setPart("settings", { ...value.settings, socialLinks: [...value.settings.socialLinks, { id: newStableId("social"), label: "Instagram", url: "https://instagram.com/", visible: false, order: value.settings.socialLinks.length + 1 }] })}><Plus size={14} />{labels.addSocial}</button></Card></div>}
    {tab === "seo" && <div className="cms-stack"><Card title={labels.globalSeo}><LocalizedFields language={language} label={labels.defaultTitle} value={value.seo.defaultTitle} onChange={(defaultTitle) => setPart("seo", { ...value.seo, defaultTitle })} /><LocalizedFields language={language} label={labels.defaultDescription} value={value.seo.defaultDescription} multiline onChange={(defaultDescription) => setPart("seo", { ...value.seo, defaultDescription })} />{imageField(labels.share, value.seo.shareImage, (shareImage) => setPart("seo", { ...value.seo, shareImage }))}</Card><Card title={labels.pageSeo}><label className="cms-field"><span>{labels.page}</span><SelectField value={selectedPage} onChange={(event) => setSelectedPage(event.target.value as typeof selectedPage)}>{Object.entries(value.seo.pages).map(([key]) => <option key={key} value={key}>{pageNames[language][key] ?? key}</option>)}</SelectField></label><LocalizedFields language={language} label={labels.seoTitle} value={value.seo.pages[selectedPage].title} onChange={(title) => setPart("seo", { ...value.seo, pages: { ...value.seo.pages, [selectedPage]: { ...value.seo.pages[selectedPage], title } } })} /><LocalizedFields language={language} label={labels.seoDescription} value={value.seo.pages[selectedPage].description} multiline onChange={(description) => setPart("seo", { ...value.seo, pages: { ...value.seo.pages, [selectedPage]: { ...value.seo.pages[selectedPage], description } } })} />{imageField(labels.shareImage, value.seo.pages[selectedPage].socialImage, (socialImage) => setPart("seo", { ...value.seo, pages: { ...value.seo.pages, [selectedPage]: { ...value.seo.pages[selectedPage], socialImage } } }))}</Card></div>}
    {tab === "appearance" && <Card title={labels.colors}><div className="cms-color-grid">{([["primary", "primary"], ["accent", "accent"], ["surface", "surface"], ["ink", "ink"]] as const).map(([key, label]) => <label className="cms-color" key={key}><span>{labels[label]}</span><input type="color" value={value.theme[key]} onChange={(event) => setPart("theme", { ...value.theme, [key]: event.target.value })} /><code>{value.theme[key]}</code></label>)}</div><p className="cms-hint">{labels.sync}</p></Card>}
    {tab === "media" && <Card title={`${labels.library} · ${media.length}`}><label className="cms-upload-large"><ImagePlus size={20} /><span>{labels.upload}</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(event) => { void addMedia(() => undefined, event.currentTarget.files?.[0]); event.currentTarget.value = ""; }} /></label><p className="cms-hint">JPEG, PNG, WebP, AVIF · max 8 MB. {labels.used}</p><div className="cms-media-grid">{media.map((asset) => { const used = asset.used || JSON.stringify(value).includes(asset.image); return <article className="cms-media-card" key={asset.image}><img src={asset.image} alt=""/><div><b>{asset.name}</b><small>{used ? labels.used : labels.library}</small>{asset.deletable && <button disabled={used} className="cms-delete" aria-label={labels.delete} onClick={() => void deleteMedia(asset)}><Trash2 size={15}/></button>}</div></article>; })}</div>{!media.length && <p className="admin-empty">{labels.noItems}</p>}</Card>}
    <div className="cms-sticky-save">{saveButton}<span><Check size={15} />{labels.sync}</span></div>
  </div>;
}

function LinkEditor({ item, language, labels, onChange, onDelete }: { item: ManagedLink; language: Lang; labels: Record<string, string>; onChange: (value: ManagedLink) => void; onDelete: () => void }) {
  return <details className="cms-entity"><summary className="cms-entity-title"><b>{item.label[language]}</b><button type="button" className="cms-delete" aria-label={labels.delete} onClick={(event) => { event.preventDefault(); event.stopPropagation(); onDelete(); }}><Trash2 size={15}/></button><span className="cms-expand-label"><ChevronDown size={14}/>{labels.showMore}</span><span className="cms-collapse-label"><ChevronDown size={14}/>{labels.showLess}</span></summary><div className="cms-entity-body"><Field label={labels.id} value={item.id} onChange={(id) => onChange({ ...item, id: safeId(id) })}/><LocalizedFields language={language} label={labels.name} value={item.label} onChange={(label) => onChange({ ...item, label })}/><Field label={labels.href} value={item.href} onChange={(href) => onChange({ ...item, href })}/><div className="cms-grid"><Field label={labels.order} value={item.order} type="number" onChange={(raw) => onChange({ ...item, order: Number(raw) })}/><Toggle label={labels.visible} checked={item.visible} onChange={(visible) => onChange({ ...item, visible })}/></div></div></details>;
}
